import{_ as e,o as a,c as l,a3 as d}from"./chunks/framework.Cr9EE2ob.js";const h=JSON.parse('{"title":"Feature coverage","description":"What yarilo implements, feature by feature, so that planning a migration is a matter of reading a list rather than of trying things out.","frontmatter":{"head":[["meta",{"name":"robots","content":"noindex"}],["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/architecture/parity.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/main/architecture/parity.html"}],["meta",{"property":"og:title","content":"Feature coverage"}],["meta",{"name":"twitter:title","content":"Feature coverage"}],["meta",{"property":"og:description","content":"What yarilo implements, feature by feature, so that planning a migration is a matter of reading a list rather than of trying things out."}],["meta",{"name":"twitter:description","content":"What yarilo implements, feature by feature, so that planning a migration is a matter of reading a list rather than of trying things out."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/main/architecture/parity.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/main/architecture/parity.html\\",\\"headline\\":\\"Feature coverage\\",\\"description\\":\\"What yarilo implements, feature by feature, so that planning a migration is a matter of reading a list rather than of trying things out.\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/main/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Feature coverage\\",\\"item\\":\\"https://doc.yarilomail.org/main/architecture/parity.html\\"}]}]}"]]},"headers":[],"relativePath":"architecture/parity.md","filePath":"architecture/parity.md","lastUpdated":1793450621000}'),i={name:"architecture/parity.md"};function n(s,t,r,o,g,y){return a(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="feature-coverage" tabindex="-1">Feature coverage <a class="header-anchor" href="#feature-coverage" aria-label="Permalink to &quot;Feature coverage&quot;">​</a></h1><p>What yarilo implements, feature by feature, so that planning a migration is a matter of reading a list rather than of trying things out.</p><p>Three values are used, and <strong>no</strong> is as legitimate an answer as <strong>yes</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>yes</strong></td><td style="text-align:left;">implemented and exercised by tests; a configuration that uses it has an equivalent here</td></tr><tr><td style="text-align:left;"><strong>partial</strong></td><td style="text-align:left;">usable, with a stated limit - read the note before relying on it</td></tr><tr><td style="text-align:left;"><strong>no</strong></td><td style="text-align:left;">not implemented. Where an issue exists it is linked, and that issue is where the plan lives</td></tr></tbody></table><p>This page is maintained in the same change that alters coverage: a row is updated by the PR that moves it, not by a later sweep. A matrix that lags is worse than none, because every row here is a promise somebody may migrate on.</p><p>The IMAP extension table below is <strong>exhaustive for what is advertised</strong>: every capability in the server&#39;s <code>CAPABILITY</code> reply has a row here, and the rows marked <code>no</code> name the notable extensions that are not advertised. Where this page and a protocol page disagree, this one is the one kept current - the disagreement is a bug in the other, and both are fixed together.</p><p>Version: <strong>2.4.x line</strong> (stable), from 2.4.1. Last reviewed 2026-10-04.</p><h2 id="protocols" tabindex="-1">Protocols <a class="header-anchor" href="#protocols" aria-label="Permalink to &quot;Protocols&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">yarilo</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">IMAP4rev1 / IMAP4rev2</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 3501 / RFC 9051</td></tr><tr><td style="text-align:left;">POP3</td><td style="text-align:left;">yes</td><td style="text-align:left;">including <code>TOP</code>, <code>UIDL</code></td></tr><tr><td style="text-align:left;">LMTP</td><td style="text-align:left;">yes</td><td style="text-align:left;">delivery, proxying to backends, a synthesised <code>Message-ID</code> when one is missing</td></tr><tr><td style="text-align:left;">Submission (MSA)</td><td style="text-align:left;">yes</td><td style="text-align:left;">separate service, relay to an external MTA</td></tr><tr><td style="text-align:left;">ManageSieve</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 5804</td></tr><tr><td style="text-align:left;">JMAP</td><td style="text-align:left;">partial</td><td style="text-align:left;"><strong>reads, writes, submits, and pushes over EventSource and WebSocket.</strong> <code>Mailbox/<wbr>{get,query,set,changes}</code>, <code>Email/<wbr>{get,query,set,import,changes}</code> (<code>Email/<wbr>set</code> creates, updates keywords and <code>mailboxIds</code>, and destroys), <code>Thread/<wbr>{get,changes}</code>, <code>SearchSnippet/<wbr>get</code>, blob upload and download, back-references and creation ids across calls, real state strings. <code>Quota/<wbr>{get,changes,query,queryChanges}</code> (RFC 9425, read-only). <code>SieveScript/<wbr>{get,set,query,validate}</code> (RFC 9661) over the ManageSieve store; <code>VacationResponse/<wbr>{get,set}</code> as the managed Sieve script ManageSieve also sees. <code>EmailSubmission/<wbr>{get,set,query,queryChanges,changes}</code> and <code>Identity/<wbr>{get,changes,set}</code> when a Submission relay is configured; the login address and <code>identity_<wbr>aliases</code> give the account&#39;s own identities, and <code>Identity/<wbr>set</code> creates, changes and destroys further ones. JMAP over WebSocket (RFC 8887), with push, is served; PushSubscription (Web Push) is not implemented. <code>Email/<wbr>queryChanges</code> and <code>Mailbox/<wbr>queryChanges</code> answer <code>cannotCalculateChanges</code> by design - a query result depends on its filter and sort, and this server keeps no per-client result set, so <code>canCalculateChanges</code> is advertised as <code>false</code>. See <a href="/main/protocols/jmap.html#capabilities">JMAP</a></td></tr></tbody></table><h2 id="imap-extensions" tabindex="-1">IMAP extensions <a class="header-anchor" href="#imap-extensions" aria-label="Permalink to &quot;IMAP extensions&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Extension</th><th style="text-align:left;">yarilo</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">IDLE, UNSELECT, LITERAL+, ENABLE, SASL-IR</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">UIDPLUS, MOVE, NAMESPACE</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">CONDSTORE / QRESYNC</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 7162</td></tr><tr><td style="text-align:left;">ESEARCH, SEARCHRES</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 4731</td></tr><tr><td style="text-align:left;">LIST-EXTENDED, LIST-STATUS, STATUS=SIZE</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">SPECIAL-USE, CREATE-SPECIAL-USE</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 6154</td></tr><tr><td style="text-align:left;">SORT</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 5256, all keys; <code>SORT=DISPLAY</code> (RFC 5957) is not implemented</td></tr><tr><td style="text-align:left;">THREAD</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 5256, <code>REFERENCES</code> and <code>ORDEREDSUBJECT</code></td></tr><tr><td style="text-align:left;">OBJECTID</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 8474 - <code>MAILBOXID</code>, <code>EMAILID</code>, <code>THREADID</code></td></tr><tr><td style="text-align:left;">BINARY</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 3516</td></tr><tr><td style="text-align:left;">NOTIFY</td><td style="text-align:left;">partial</td><td style="text-align:left;">RFC 5465; annotation/metadata events are not reported</td></tr><tr><td style="text-align:left;">METADATA</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 5464, when a metadata dict is configured</td></tr><tr><td style="text-align:left;">ACL</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 4314, enforced on every path - <strong>off by default</strong> (<code>acl.<wbr>enabled</code>); a configuration with a shared, public or other users namespace and ACL off is refused at startup. See <a href="/main/storage/namespace.html">Namespaces</a></td></tr><tr><td style="text-align:left;">QUOTA</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 9208</td></tr><tr><td style="text-align:left;">ID</td><td style="text-align:left;">yes</td><td style="text-align:left;">RFC 2971; always offered before login, after login only while <code>imap_<wbr>id_<wbr>send</code> is non-empty</td></tr><tr><td style="text-align:left;">COMPRESS</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">URLAUTH, CATENATE, BURL</td><td style="text-align:left;">no</td><td style="text-align:left;">RFC 4467 / RFC 4469 / RFC 4468. Until 2026-08-25 the IMAP page listed URLAUTH as supported; it never was, and the claim is removed rather than kept</td></tr><tr><td style="text-align:left;">SEARCH=FUZZY, CONTEXT=SEARCH, CONTEXT=SORT, ESORT</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">REPLACE, SAVEDATE, PREVIEW</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">I18NLEVEL</td><td style="text-align:left;">no</td><td style="text-align:left;">collation follows <code>i;unicode-casemap</code> in SORT/THREAD, but the extension is not advertised</td></tr></tbody></table><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Format</th><th style="text-align:left;">yarilo</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Maildir</td><td style="text-align:left;">yes</td><td style="text-align:left;">Maildir++, filename and flag conventions match</td></tr><tr><td style="text-align:left;">sdbox</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">mdbox</td><td style="text-align:left;">yes</td><td style="text-align:left;">including the map, alt storage, and <code>purge</code></td></tr><tr><td style="text-align:left;">mbox</td><td style="text-align:left;">no</td><td style="text-align:left;">no plan; the format is legacy everywhere it still appears</td></tr><tr><td style="text-align:left;">obox / object storage</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">Index format</td><td style="text-align:left;">yes</td><td style="text-align:left;">the established on-disk index layout, byte-compatible where documented</td></tr></tbody></table><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">yarilo</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">SASL PLAIN / LOGIN</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">SASL SCRAM-SHA-1 / SHA-1-PLUS / SHA-256 / SHA-256-PLUS</td><td style="text-align:left;">yes</td><td style="text-align:left;">IMAP, POP3 and submission, channel binding included</td></tr><tr><td style="text-align:left;">SASL XOAUTH2 / OAUTHBEARER</td><td style="text-align:left;">yes</td><td style="text-align:left;">IMAP, POP3 and submission, run by <code>yarilo-auth</code> with token introspection; RFC 7628 failure with the client&#39;s acknowledgement</td></tr><tr><td style="text-align:left;">SASL CRAM-MD5, DIGEST-MD5</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">SASL EXTERNAL (client certificates)</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">SASL GSSAPI / Kerberos</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">passdb/userdb: SQL (MySQL, PostgreSQL, SQLite)</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">passdb/userdb: passwd-file, static</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">passdb/userdb: LDAP, PAM, Lua, IMAP</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">Password schemes</td><td style="text-align:left;">partial</td><td style="text-align:left;"><code>PLAIN</code>, <code>CLEARTEXT</code>, <code>CRYPT</code>, <code>BCRYPT</code>/<code>BLF-CRYPT</code>, <code>SHA512-CRYPT</code>, <code>SCRAM-SHA-1</code>, <code>SCRAM-SHA-256</code>. The older MD5 and SHA1 scheme families are not implemented</td></tr><tr><td style="text-align:left;">Master users</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">Auth policy / penalty (weakforced-style)</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr></tbody></table><h2 id="filtering-and-delivery" tabindex="-1">Filtering and delivery <a class="header-anchor" href="#filtering-and-delivery" aria-label="Permalink to &quot;Filtering and delivery&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">yarilo</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Sieve (RFC 5228)</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">Sieve extensions</td><td style="text-align:left;">yes</td><td style="text-align:left;">43 extensions, including <code>imap4flags</code>, <code>editheader</code>, <code>enotify</code>, <code>imapsieve</code>, <code>mailboxid</code>, <code>spamtest</code>/<code>virustest</code> and the RFC 5703 MIME set. The full list is on the <a href="/main/features/sieve.html">Sieve page</a> rather than repeated here - one list cannot disagree with itself</td></tr><tr><td style="text-align:left;">Sieve <code>pipe</code> / external programs</td><td style="text-align:left;">yes</td><td style="text-align:left;">with a configured binary directory</td></tr><tr><td style="text-align:left;">Local delivery agent</td><td style="text-align:left;">partial</td><td style="text-align:left;">delivery is via LMTP; there is no standalone local-delivery binary</td></tr><tr><td style="text-align:left;">Recipient rate limiting</td><td style="text-align:left;">yes</td><td style="text-align:left;">cluster-wide, per (sender IP, recipient)</td></tr></tbody></table><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">yarilo</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">FTS with Xapian (flatcurve)</td><td style="text-align:left;">yes</td><td style="text-align:left;">separate <code>yarilo-fts</code> service</td></tr><tr><td style="text-align:left;">FTS: Solr, Elasticsearch</td><td style="text-align:left;">no</td><td style="text-align:left;">the engine is pluggable, no other engine is implemented</td></tr><tr><td style="text-align:left;">Language handling, stemming</td><td style="text-align:left;">yes</td><td style="text-align:left;">per-language filters, tokeniser knobs</td></tr></tbody></table><h2 id="quota" tabindex="-1">Quota <a class="header-anchor" href="#quota" aria-label="Permalink to &quot;Quota&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">yarilo</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Storage and message-count quotas</td><td style="text-align:left;">yes</td><td style="text-align:left;">counted from the index, no dict drift</td></tr><tr><td style="text-align:left;"><code>quota_<wbr>rule</code> / per-user overrides</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">Quota warnings</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>quota-status</code> policy service for MTAs</td><td style="text-align:left;">yes</td><td style="text-align:left;">separate service</td></tr></tbody></table><h2 id="clustering-and-operations" tabindex="-1">Clustering and operations <a class="header-anchor" href="#clustering-and-operations" aria-label="Permalink to &quot;Clustering and operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">yarilo</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Director (per-user backend affinity)</td><td style="text-align:left;">yes</td><td style="text-align:left;">own ring and peer sync, plus a per-user flush hook (<code>flush_<wbr>program</code>) - see <a href="/main/architecture/director.html">Director</a></td></tr><tr><td style="text-align:left;">Replication (dsync)</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">Shared and public namespaces</td><td style="text-align:left;">partial</td><td style="text-align:left;">namespaces and ACLs work; cross-user delivery and some enforcement gaps remain</td></tr><tr><td style="text-align:left;">Virtual mailboxes</td><td style="text-align:left;">partial</td><td style="text-align:left;">a namespace whose mailboxes are defined by a configuration file of folders and <code>SEARCH</code> rules; kept in sync while open, with <code>FETCH</code>, <code>SEARCH</code>, <code>SORT</code>, <code>THREAD</code>, <code>STORE</code>, <code>EXPUNGE</code>, <code>COPY</code> and <code>MOVE</code> acting on the real message, <code>APPEND</code>/<code>COPY</code>/<code>MOVE</code> into one storing to its save folder, and annotation lines filtering the folders. A virtual mailbox has <code>\\Recent</code> messages of its own, and <code>+</code> takes a folder&#39;s. See <a href="/main/features/virtual.html">Virtual Mailboxes</a></td></tr><tr><td style="text-align:left;">imap-hibernate</td><td style="text-align:left;">no</td><td style="text-align:left;">idle IMAP sessions are not parked into a separate process; each holds its own. No issue open yet - this row is the record</td></tr><tr><td style="text-align:left;">Prometheus metrics, health endpoints</td><td style="text-align:left;">yes</td><td style="text-align:left;">per-command latencies, storage and index counters, <code>/<wbr>healthz</code> and <code>/<wbr>readyz</code></td></tr><tr><td style="text-align:left;">Command-line administration</td><td style="text-align:left;">yes</td><td style="text-align:left;"><code>yarctl</code> covers the operations the services expose - routing, storage, index, quota, ACL, metadata, sessions, auth - and each family is documented on the <a href="/main/operations/yarilo_admin.html">administration page</a>. The command set is not a one-to-one map of any other server&#39;s, so a migrated runbook is translated rather than copied</td></tr></tbody></table><h2 id="what-migration-involves" tabindex="-1">What migration involves <a class="header-anchor" href="#what-migration-involves" aria-label="Permalink to &quot;What migration involves&quot;">​</a></h2><p>Configuration keys keep their established names where the setting means the same thing, so translating an existing configuration into <code>yarilo.<wbr>yaml</code> is mechanical for the covered surface. The on-disk formats - Maildir, dbox, the index - are the same layouts, which is what makes a migration a matter of pointing yarilo at existing mail rather than converting it.</p><p>Where a row above says <strong>no</strong>, a configuration that relies on that feature has no equivalent here yet, and the linked issue is the honest state of the plan.</p>',26)])])}const f=e(i,[["render",n]]);export{h as __pageData,f as default};
